function checkPrime(nums) {
  // Loop through all the numbers in the array
  for (let i = 0; i < nums.length; i++) {
    // If the current number is less than or equal to 1, it is not a prime number
    if (nums[i] <= 1) {
      continue;
    }
    // Check if the current number is divisible by any prime number
    for (let j = 2; j < Math.sqrt(nums[i]); j++) {
      if (nums[i] % j === 0) {
        // If it is divisible, it is not a prime number
        break;
      }
    }
    // If we reach this point, it means the current number is prime
    console.log(`The number ${nums[i]} is a prime number`);
    return;
  }
  // If none of the numbers is prime, print "No prime number found"
  console.log("No prime number found");
}
