Sure! One programming problem involving dynamic programming involves solving the Longest Common Substring (LCS) problem.

Problem Description: Given two strings (e.g., "ACGTTACGTTACGTATGCAT" and "CGAGAAGATCTTCAT"), find the longest substring that appears in both strings.

Examples:

1. Input: "ACGTTACGTTACGTATGCAT" and "CGAGAAGATCTTCAT"
Output: "AGAAGAT"
Explanation: This is the longest substring that appears in both strings.

2. Input: "ACGTTACGTTACGTATGCAT" and "ATGCAGT"
Output: "TACG"
Explanation: This is the longest substring that appears in both strings.

3. Input: "ACGTAGCTCAGTCTA" and "CTAGCTCAGTCTACGT"
Output: "CAGTCTA"
Explanation: This is the longest substring that appears in both strings.

Constraints:

1. The strings will only contain the characters: 'A', 'C', 'G', and 'T'.

2. The length of each string will be <= 1000.

3. The strings will not contain any characters besides the specified characters.

This problem can be solved using dynamic programming. We'll use a 2D array to store the lengths of the longest common substrings.

```cpp
#include <iostream>
#include <string>
using namespace std;

int lcs(string &s1, string &s2, int m, int n) {
    int lengths[m + 1][n + 1];
    for (int i = 0; i <= m; i++) {
        for (int j = 0; j <= n; j++) {
            if (i == 0 || j == 0) {
                lengths[i][j] = 0;
            } else if (s1[i - 1] == s2[j - 1]) {
                lengths[i][j] = lengths[i - 1][j - 1] + 1;
            } else {
                lengths[i][j] = max(lengths[i - 1][j], lengths[i][j - 1]);
            }
        }
    }

    int result = lengths[m][n];
    string lcsStr = "";
    for (int i = m; i > 0; i--) {
        for (int j = n; j > 0; j--) {
            if (lengths[i][j] == result && s1[i - 1] == s2[j - 1]) {
                lcsStr = s1[i - 1] + lcsStr;
                result--;
                break;
            }
        }
    }
    cout << "Result: " << lcsStr << endl;
    return result;
}

int main() {
    string s1, s2;
    cout << "Enter First String: ";
    cin >> s1;
    cout << "Enter Second String: ";
    cin >> s2;
    int m = s1.size();
    int n = s2.size();
    lcs(s1, s2, m, n);
}
